n("אדם", "המילה אדם קרובה בעברית למילים אדמה ואדום, ובתורה האדם הראשון נוצר מעפר האדמה. בעברית של היום אדם הוא גם פשוט בן אדם, כל אחד ואחת. השם מוכר גם בערבית ובשפות רבות באותו צליל.")
n("מרים", "בתורה מרים היא אחות משה ואהרון, שיצאה בתוף ובמחול אחרי חציית הים. מקור השם לא ברור, ויש לו כמה הסברים. מהשם הזה התפתחו צורות רבות בשפות אחרות, כמו מריה, ובעברית גם הצורה הקצרה מירי.", ["מירי"])
n("ארי", "ארי היא אחת המילים לאריה בעברית המקראית, והיא מופיעה בשירה ובברכות לצד המילה לביא. היא גם החלק הראשון של השם אריאל, ארי של אל. השם קצר וקל להגייה בעברית ובשפות אחרות.", ["אריאל", "אריה"])
n("שרה", "בעברית המקראית שׂרה היא אישה בעלת מעמד, הצורה הנקבית של שׂר. בתורה שמה הראשון היה שׂרי, והשם הוחלף לשׂרה יחד עם ההבטחה שייוולד לה בן. שרה היא אשת אברהם ואמו של יצחק.", ["שרי"])
n("אליה", "אליה הוא צורה של השם אליהו, ושניהם מחברים את אלי עם שם ה׳. בתנ״ך אליהו הנביא פועל בימי אחאב המלך, ובספר מלאכי הוא נקרא אליה. בישראל השם ניתן היום גם לבנות.", ["אליהו"])
