n("יצחק", "בתורה שרה צוחקת כשהיא שומעת שתלד בן בזקנתה, והשם יצחק נשאר כזיכרון לצחוק הזה. יצחק הוא בנם של אברהם ושרה ואביהם של יעקב ועשו. בערבית השם מוכר בצורה אִסְחָאק.")
n("אוריה", "השם מחבר את המילה אורי עם יה, שם ה׳, כמו בשמות עבריים רבים שמסתיימים ביה. בתנ״ך אוריה הכהן הוא אחד העדים הנאמנים בספר ישעיהו. מאותה מילה נבנו גם אור, אורי ואוריאל, ובכתיב יש גם את הצורה אורייה.", ["אורי", "אור", "אורייה", "אוריאל"])
n("שמואל", "בספר שמואל חנה קוראת לבנה שמואל, כי שאלה אותו מה׳ ונענתה. שמואל גדל במשכן בשילה, ונעשה נביא ושופט. השם מוכר גם בשפות רבות, כמו סמואל באנגלית.")
n("אלה", "האלה היא עץ חסון שגדל בחורש של הארץ, והיא יכולה לחיות מאות שנים. בתנ״ך עמק האלה הוא המקום שבו עמדו מחנות ישראל ופלשתים זה מול זה. העמק נמצא בשפלת יהודה, ונקרא כך גם היום.")
n("אדל", "אדל הוא שם אירופי, שבא ממילה גרמנית עתיקה שקשורה לאצולה. מאותה מילה באים גם השמות אדלה ואדלייד, שהיו מוכרים באירופה כבר בימי הביניים. בעברית השם נשמע קצר ונכתב בשלוש אותיות.")
n("חיה", "השם בנוי על השורש ח־י־ה, כמו המילים חיים וחי, והוא צורה נקבית של השם חיים. ביידיש הוא נשמע חַיֶּה, ומכאן גם צורות חיבה כמו חייקה. בעברית של היום חיה היא גם בעל חיים, אבל השם בא מהחיים עצמם.", ["חיים", "חי"])
n("אימרי", "אמרים הם דיבורים ומילים, והצורה אמרי פירושה המילים שלי. המילה מופיעה בתהילים, בתפילה שהדיבור יהיה לרצון. בכתיב אפשר לפגוש גם את הצורה אמרי, בלי יו״ד.", ["אמרי"])
n("איתי", "השם בנוי על המילה איתי, מלשון עם, כלומר מי שנמצא לצדי. בתנ״ך אתי הגתי הוא איש שבחר להישאר עם דוד כשברח מירושלים, אף שלא היה מישראל. השם איתיאל, אל איתי, בנוי על אותה מילה.", ["איתיאל"])
n("גפן", "הגפן היא אחד משבעת המינים שהארץ נשתבחה בהם, וממנה באים הענבים והיין. בתנ״ך היא מופיעה פעמים רבות כסמל לשפע ולחיים שלווים. בעברית של היום השם ניתן לבנים ולבנות.")
n("חיים", "השם הוא המילה חיים עצמה, שבאה בעברית בצורת רבים כמו מים ושמים. מאותו שורש באים גם השמות חיה וחי. ביידיש השם נשמע כַיִים, ובמבטא הזה הוא מוכר בקהילות אשכנז.", ["חיה", "חי"])
n("רבקה", "בתורה רבקה היא בתו של בתואל מארם נהריים, שהשקתה את גמלי עבד אברהם ליד הבאר ונעשתה אשת יצחק. היא אמם של יעקב ועשו. יש שקושרים את השם למילה מרבק, המקום שבו קושרים עגלים.", ["רבקי"])
n("רחל", "בעברית המקראית רחל היא כבשה, ושמה של אחת האמהות בא מעולם הרועים. בתורה רחל פוגשת את יעקב ליד הבאר כשהיא רועה את צאן אביה, והוא עובד שבע שנים כדי לשאת אותה. קבר רחל, בדרך לבית לחם, מוזכר כבר בתורה.", ["רחלי"])
n("אחמד", "השם בנוי על השורש הערבי ח־מ־ד, שעניינו שבח ותהילה, כמו השמות מוחמד ומחמוד. אחמד היא צורת יתרון בערבית, ולכן השם מתפרש כמי שראוי לשבח יותר מכל. בכתיב עברי השם נכתב כמו שהוא נשמע.", ["מוחמד", "מחמד", "מחמוד"])
n("אהרון", "בתורה אהרון הוא אחיו הגדול של משה, שדיבר בשמו לפני פרעה ונעשה הכהן הראשון. משמו בא המושג בני אהרון, הכוהנים. בכתיב המקראי השם נכתב אהרן, בלי וו.")
